package com.yihe.framework.ehr;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
@Service @SuppressWarnings("unchecked")
public class ComprehensiveHealthService {
 final EhrRepository db;final EhrService ehr;final EmployeeHealthArchiveService employees;final DigitalWorkerSettings settings;
 static final Set<String> DOMAIN=new HashSet<>(Arrays.asList("hypertension","diabetes","lipids","fatty_liver","cardiovascular","dust","noise","gas","heat","occupational"));
 public ComprehensiveHealthService(EhrRepository db,EhrService ehr,EmployeeHealthArchiveService employees){this.db=db;this.ehr=ehr;this.employees=employees;this.settings=new DigitalWorkerSettings(db);}
 void allow(EhrActor a,boolean write){require(!a.mobile,403,"个人端无综合评估管理权限");if(write)require(a.doctor,403,"综合评估操作需要医生权限");}
 Object canonical(Object value){if(value instanceof Map){Map<String,Object> m=new TreeMap<>();((Map<?,?>)value).forEach((k,v)->m.put(String.valueOf(k),canonical(v)));return m;}if(value instanceof List){List<Object> list=new ArrayList<>();for(Object v:(List<?>)value)list.add(canonical(v));return list;}return value;}
 String hash(Object value){return hex(digest(bytes(ehr.encode(canonical(value)))));}
 Map<String,Object> source(EhrActor a,String record){Map<String,Object> p=employees.detail(a,record);p.remove("logs");p.remove("serviceTasks");return new AssessmentRuleRuntime(db,ehr).attach(a,"comprehensive",p);}
 String sourceHash(Map<String,Object> p){Map<String,Object> person=new TreeMap<>();for(String k:Arrays.asList("id","name","code","sex","birth","age","org","team","job","exposure","rowVersion"))person.put(k,p.get(k));List<Object> reports=new ArrayList<>();for(Object v:(List<?>)p.get("reports")){Map<?,?> r=(Map<?,?>)v;reports.add(map("id",r.get("id"),"revision",r.get("revision"),"etag",r.get("etag")));}Map<String,Object> signature=map("person",person,"reports",reports);if(p.containsKey("assessmentRules"))signature.put("assessmentRules",p.get("assessmentRules"));return hash(signature);}
 Map<String,Object> latest(EhrActor a,String record){return db.one("SELECT * FROM a_comprehensive_analyses WHERE scope_code=? AND data_mode=? AND record_id=? ORDER BY created_at DESC,analysis_id DESC LIMIT 1",a.scope,a.mode,record);}
 Map<String,Object> owned(EhrActor a,String record,String id,boolean lock){ehr.profile(a,record,false);Map<String,Object> row=db.one("SELECT * FROM a_comprehensive_analyses WHERE analysis_id=? AND scope_code=? AND data_mode=? AND record_id=?"+(lock?" FOR UPDATE":""),id,a.scope,a.mode,record);require(row!=null,404,"综合评估不存在或无权限");return row;}
 public Map<String,Object> detail(EhrActor a,String record,String analysis){allow(a,false);Map<String,Object> facts=source(a,record),latest=latest(a,record),selected=analysis==null||analysis.isEmpty()?latest:owned(a,record,analysis,false);Map<String,Object> review=selected==null?null:db.one("SELECT * FROM a_comprehensive_reviews WHERE scope_code=? AND data_mode=? AND record_id=? AND analysis_id=?",a.scope,a.mode,record,selected.get("analysis_id"));if(review!=null)review.put("content",ehr.decode(review.get("review_json")));return map("person",facts,"analysis",selected,"review",review,"sourceDigest",sourceHash(facts),"sourceChanged",selected!=null&&!sourceHash(facts).equals(selected.get("source_digest")),"historical",selected!=null&&latest!=null&&!selected.get("analysis_id").equals(latest.get("analysis_id")),"canReview",a.doctor,"candidateOnly",ehr.candidateOnly,"history",db.all("SELECT a.analysis_id id,a.analysis_state state,a.requested_by requestedBy,a.created_at createdAt,a.finished_at finishedAt,r.review_id reviewId,r.reviewer,r.published,r.created_at reviewedAt FROM a_comprehensive_analyses a LEFT JOIN a_comprehensive_reviews r ON r.analysis_id=a.analysis_id AND r.scope_code=a.scope_code AND r.data_mode=a.data_mode WHERE a.scope_code=? AND a.data_mode=? AND a.record_id=? ORDER BY a.created_at DESC,a.analysis_id DESC LIMIT 50",a.scope,a.mode,record));}
 @Transactional public Map<String,Object> begin(EhrActor a,String record,Map<String,Object> body){allow(a,true);ehr.profile(a,record,true);String key=text(body,"requestKey");require(key.matches("[0-9a-fA-F-]{36}"),422,"请求键无效");String digest=hash(body);Map<String,Object> receipt=db.one("SELECT * FROM a_comprehensive_analyses WHERE scope_code=? AND data_mode=? AND request_key=?",a.scope,a.mode,key);if(receipt!=null){require(record.equals(receipt.get("record_id"))&&digest.equals(receipt.get("payload_digest")),409,"请求键已用于不同内容");receipt.put("replayed",true);return receipt;}
 Map<String,Object> policy=settings.lock(a,"assess");settings.requireAi(policy);settings.admit(a,"assess","assessment",policy);db.exec("UPDATE a_comprehensive_analyses SET analysis_state='failed',error_code='ANALYSIS_EXPIRED',row_version=row_version+1,finished_at=UTC_TIMESTAMP(6) WHERE scope_code=? AND data_mode=? AND record_id=? AND analysis_state='pending' AND lease_until<UTC_TIMESTAMP(6)",a.scope,a.mode,record);require(db.count("SELECT COUNT(*) FROM a_comprehensive_analyses WHERE scope_code=? AND data_mode=? AND record_id=? AND analysis_state='pending'",a.scope,a.mode,record)==0,409,"该职工已有综合分析进行中，请等待或取消后重试");Map<String,Object> facts=source(a,record);require(sourceHash(facts).equals(text(body,"sourceDigest")),409,"档案或报告已有变化，请刷新后再评估");List<?> reports=(List<?>)facts.get("reports");require(!reports.isEmpty(),422,"请先关联体检报告");require(reports.stream().anyMatch(r->!((List<?>)((Map<?,?>)r).get("items")).isEmpty()),422,"报告尚无结构化检查结果，请先识别与核对");require(ehr.encode(facts).length()<=1800000,422,"关联资料过多，请先整理报告后再评估");String id=id();db.insert("a_comprehensive_analyses",map("analysis_id",id,"scope_code",a.scope,"data_mode",a.mode,"record_id",record,"request_key",key,"payload_digest",digest,"source_digest",sourceHash(facts),"source_json",ehr.encode(facts),"analysis_state","pending","requested_by",a.user,"created_at",now()));db.exec("UPDATE a_comprehensive_analyses SET lease_until=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 20 MINUTE) WHERE analysis_id=?",id);ehr.audit(a,record,null,null,"comprehensive_requested","已按授权资料保存综合分析来源快照");return owned(a,record,id,false);}
 public Map<String,Object> modelInput(Map<String,Object> task){Map<String,Object> facts=(Map<String,Object>)ehr.decode(task.get("source_json"));return map("worker_id","assess","task_type","comprehensive_assessment","title","个人综合健康评估","instructions","依据当前职工全部已提供的体检报告、原始值与单位、历史年份及岗位职业接触资料进行综合分析。分为分析摘要、体检指标线索、历史变化、慢病相关线索、职业接触相关线索、待核实事项、医生审核要点。每项注明报告日期与原件页码，不把不同单位数值直接比较。生活习惯、既往史、家族史若缺失明确未提供，不虚构。不得生成综合分数或确定风险等级；不得诊断、开药、修改档案或声称已执行干预。报告候选结果需明确待核对。输入是结构化原文与出处，不宣称直接读取PDF图像。","archive_context",map("linked",true,"person",facts,"reports",facts.get("reports")));}
 @Transactional public void finish(EhrActor a,String record,String id,String output,String failure){Map<String,Object> t=owned(a,record,id,true);if(!"pending".equals(t.get("analysis_state")))return;boolean authorized=db.count("SELECT COUNT(*) FROM yh_user_reginfo WHERE user_code=? AND User_Type=4 AND lock_flag=2 AND CONCAT('org:',Org_Code)=?",a.user,a.scope)>0;String error=failure;if(!authorized)error="ANALYSIS_ACCESS_REVOKED";if(!sourceHash(source(a,record)).equals(t.get("source_digest")))error="ANALYSIS_SOURCE_CHANGED";boolean ok=error==null&&output!=null&&!output.trim().isEmpty();db.exec("UPDATE a_comprehensive_analyses SET analysis_state=?,output_text=?,error_code=?,finished_at=UTC_TIMESTAMP(6),lease_until=NULL,row_version=row_version+1 WHERE analysis_id=?",ok?"completed":"failed",ok?output:null,ok?null:error==null?"ANALYSIS_EMPTY":error,id);ehr.audit(a,record,null,null,ok?"comprehensive_completed":"comprehensive_failed",ok?"综合辅助分析已生成，等待医生审核":"综合分析未完成："+error);}
 @Transactional public Object cancel(EhrActor a,String record,String id,int version,String note){allow(a,true);require(!note.trim().isEmpty()&&note.length()<=1000,422,"请填写取消说明");Map<String,Object> t=owned(a,record,id,true);require(num(t.get("row_version"))==version&&"pending".equals(t.get("analysis_state")),409,"当前状态或版本不能取消");db.exec("UPDATE a_comprehensive_analyses SET analysis_state='cancelled',finished_at=UTC_TIMESTAMP(6),lease_until=NULL,row_version=row_version+1 WHERE analysis_id=?",id);ehr.audit(a,record,null,null,"comprehensive_cancelled",note);return map("cancelled",true);}
 Map<String,Object> validate(Map<String,Object> body){String risk=text(body,"riskLevel"),note=text(body,"reviewNote").trim(),basis=text(body,"scoreBasis").trim();require(Arrays.asList("low","medium","high","critical").contains(risk),422,"请由医生核定综合风险等级");require(!note.isEmpty()&&note.length()<=3000,422,"请填写审核依据，最多3000字");Object score=body.get("healthScore");if(score!=null){require(score instanceof Number&&((Number)score).doubleValue()>=0&&((Number)score).doubleValue()<=100,422,"人工健康评分应为0至100");require(!basis.isEmpty()&&basis.length()<=1500,422,"填写人工评分必须注明评分依据");}else require(basis.length()<=1500,422,"评分依据过长");Map<String,Object> risks=new LinkedHashMap<>();Object raw=body.get("domainRisks");require(raw instanceof Map,422,"分项风险格式无效");for(Object key:((Map<?,?>)raw).keySet())require(DOMAIN.contains(key),422,"不支持的风险项目");for(String key:DOMAIN){Object value=((Map<?,?>)raw).get(key);if(value==null){risks.put(key,map("level","unknown","basis",""));continue;}require(value instanceof Map,422,"分项风险格式无效");String level=str(((Map<?,?>)value).get("level")),reason=str(((Map<?,?>)value).get("basis")).trim();require(Arrays.asList("unknown","low","medium","high","critical").contains(level)&&reason.length()<=1000,422,"分项风险或依据无效");require(level.equals("unknown")||!reason.isEmpty(),422,"确认分项风险必须注明依据");risks.put(key,map("level",level,"basis",reason));}Object suggestions=body.get("recommendations");require(suggestions instanceof List&&((List<?>)suggestions).size()<=20,422,"最多20条后续建议");List<String> advice=new ArrayList<>();for(Object value:(List<?>)suggestions){require(value instanceof String&&!((String)value).trim().isEmpty()&&((String)value).length()<=1500,422,"建议应为1至1500字原文");advice.add(((String)value).trim());}return map("riskLevel",risk,"healthScore",score,"scoreBasis",basis,"reviewNote",note,"domainRisks",risks,"recommendations",advice);}
 @Transactional public Map<String,Object> review(EhrActor a,String record,Map<String,Object> body){allow(a,true);require(!ehr.candidateOnly,403,"当前环境不允许审核确认");ehr.profile(a,record,true);String key=text(body,"requestKey"),analysis=text(body,"analysisId");require(key.matches("[0-9a-fA-F-]{36}"),422,"请求键无效");String payload=hash(body);Map<String,Object> receipt=db.one("SELECT review_id,payload_digest,record_id FROM a_comprehensive_reviews WHERE scope_code=? AND data_mode=? AND request_key=?",a.scope,a.mode,key);if(receipt!=null){require(record.equals(receipt.get("record_id"))&&payload.equals(receipt.get("payload_digest")),409,"请求键内容冲突");return detail(a,record,analysis);}Map<String,Object> t=owned(a,record,analysis,true);require("completed".equals(t.get("analysis_state")),422,"请先完成综合AI辅助分析");require(analysis.equals(latest(a,record).get("analysis_id")),409,"已有新的综合分析，请审核最新版本");require(db.count("SELECT COUNT(*) FROM a_comprehensive_reviews WHERE analysis_id=?",analysis)==0,409,"该分析已经审核，不能覆盖");require(Boolean.TRUE.equals(body.get("identityVerified"))&&Boolean.TRUE.equals(body.get("sourceVerified")),422,"请核对职工身份及报告原件");Map<String,Object> facts=source(a,record);require(sourceHash(facts).equals(t.get("source_digest"))&&text(body,"sourceDigest").equals(t.get("source_digest")),409,"原始资料已变化，请重新分析");for(Object value:(List<?>)facts.get("reports")){Map<?,?> r=(Map<?,?>)value;require(Boolean.TRUE.equals(r.get("published")),422,"请先在档案审核与归档中完成所有关联报告的审核归档");}Map<String,Object> content=validate(body),profile=ehr.profile(a,record,false);String assessment=id(),review=id();db.insert("a_health_risk_assessments",ehr.scoped(a,"assessment_id",assessment,"record_id",record,"employee_id",profile.get("employee_id"),"assessment_time",now(),"risk_level",content.get("riskLevel"),"assessment_type","ai_assisted","rule_version","clinician-comprehensive-v1","assessment_status","confirmed","reviewer_ref",bytes(a.user),"reviewed_at",now()));for(Object value:(List<?>)facts.get("reports")){Map<?,?> r=(Map<?,?>)value;db.insert("a_health_risk_report_sources",ehr.scoped(a,"record_id",record,"assessment_id",assessment,"report_id",r.get("id"),"revision",r.get("revision")));}db.insert("a_comprehensive_reviews",map("review_id",review,"scope_code",a.scope,"data_mode",a.mode,"record_id",record,"analysis_id",analysis,"assessment_id",assessment,"source_digest",t.get("source_digest"),"review_json",ehr.encode(content),"reviewer",a.user,"request_key",key,"payload_digest",payload,"created_at",now()));ehr.audit(a,record,null,null,"comprehensive_reviewed","医生已核对综合分析及关联原件；人工分项结论与评分依据另存，不覆盖体检报告");return detail(a,record,analysis);}
 @Transactional public Object publish(EhrActor a,String record,String id,Map<String,Object> body){allow(a,true);require(!ehr.candidateOnly,403,"当前环境不允许发布");Map<String,Object> row=db.one("SELECT * FROM a_comprehensive_reviews WHERE review_id=? AND scope_code=? AND data_mode=? AND record_id=? FOR UPDATE",id,a.scope,a.mode,record);require(row!=null,404,"审核记录不存在");ehr.profile(a,record,true);require(row.get("analysis_id").equals(latest(a,record).get("analysis_id")),409,"已有更新的综合分析，不能发布旧版本");require(sourceHash(source(a,record)).equals(row.get("source_digest")),409,"原始资料已变化，不能发布旧结果");require(body.get("version") instanceof Number,422,"版本参数无效");if(num(row.get("published"))==1)return map("published",true,"replayed",true);require(num(body.get("version"))==num(row.get("row_version")),409,"审核记录已有变化");require(Boolean.TRUE.equals(body.get("verified")),422,"请确认发布当前已审核结果");db.exec("UPDATE a_comprehensive_reviews SET published=1,published_at=UTC_TIMESTAMP(6),row_version=row_version+1 WHERE review_id=?",id);ehr.audit(a,record,null,null,"comprehensive_published","已明确发布医生审核后的综合评估报告；未发送通知或执行干预");return map("published",true);}
}
